// More profiles: Middle East, Europe, South & Central Asia, East Asia. src = Wikipedia title.
window.ATLAS_ENTITIES.push(
// ---------------- MIDDLE EAST ----------------
{ id: "hittites", name: "Hittite Empire", start: -1650, end: -1180, lat: 40.02, lng: 34.61, r: 400, reg: "me", ev: "mixed", src: "Hittites",
  modern: "Central Turkey, northern Syria",
  sum: "A Bronze Age Anatolian superpower that rivaled Egypt, signed history's earliest surviving peace treaty, and wrote in the oldest attested Indo-European language.",
  places: [["Hattusa", "Boğazkale, Çorum Province, Turkey", 40.02, 34.61]], rel: ["egypt", "babylon"],
  s: { politics: "Fought Ramesses II at Kadesh (c. 1274 BCE), then signed a peace treaty (c. 1259 BCE) preserved in both Egyptian and Hittite versions.",
    language: "Hittite is the oldest written Indo-European language — a distant relative of English, Hindi and Persian. Deciphered by Bedřich Hrozný in 1915.",
    legacy: "The Bible's 'Hittites' were rediscovered as a real empire only in the 1900s after archives of ~30,000 tablets were found at Hattusa.",
    fun: "Iron-working was once credited to the Hittites as a 'secret weapon'; archaeologists now think iron was rare and prestigious, not a military monopoly." } },
{ id: "assyria", name: "Neo-Assyrian Empire", start: -911, end: -609, lat: 36.36, lng: 43.15, r: 700, reg: "me", ev: "documented", src: "Neo-Assyrian Empire",
  modern: "Iraq, Syria, Turkey, Israel, Egypt (briefly)",
  sum: "The first great Iron Age empire — brutal in war, brilliant in administration — whose capital Nineveh held the world's first systematically organized library.",
  places: [["Nineveh", "Mosul, Iraq", 36.36, 43.15], ["Nimrud", "near Mosul, Iraq", 36.1, 43.33]], rel: ["babylon", "israel-ancient", "persia"],
  s: { politics: "Deported conquered peoples on a massive scale — including the 'Ten Lost Tribes' of the northern Kingdom of Israel (722 BCE). Destroyed by a Babylonian–Median coalition in 612 BCE.",
    art: "Palace reliefs of lion hunts and sieges (British Museum). Winged human-headed bulls (lamassu) guarded gates — ISIS smashed several at Nimrud and Nineveh in 2015.",
    legacy: "Aramaic spread as an imperial lingua franca under Assyria and later Persia — Jesus spoke Aramaic. Modern Assyrian Christians claim descent.",
    fun: "Lord Byron's poem 'The Destruction of Sennacherib' ('The Assyrian came down like the wolf on the fold') is about Assyria's failed siege of Jerusalem in 701 BCE." } },
{ id: "israel-ancient", name: "Ancient Israel & Judah", start: -1050, end: 135, lat: 31.78, lng: 35.23, r: 130, reg: "me", ev: "mixed", src: "History of ancient Israel and Judah",
  modern: "Israel, the West Bank, parts of Jordan",
  sum: "The small kingdoms whose scriptures — the Hebrew Bible — became foundational for Judaism, Christianity and Islam, and which shaped Western law, ethics and literature.",
  places: [["Jerusalem", "Jerusalem", 31.78, 35.23], ["Samaria", "Sebastia, West Bank", 32.28, 35.19], ["Masada", "near the Dead Sea, Israel", 31.32, 35.35], ["Qumran", "West Bank (Dead Sea Scrolls)", 31.74, 35.46]],
  rel: ["assyria", "babylon", "persia", "rome-emp", "israel"],
  s: { origins: "Israelites emerged from Canaanite highland villages c. 1200–1000 BCE. The Merneptah Stele (c. 1208 BCE) is the first mention of 'Israel' outside the Bible.",
    politics: "Northern Israel fell to Assyria (722 BCE); Judah to Babylon (587/586 BCE), exiling its elite. Persia's Cyrus allowed a return; the Hasmoneans ruled independently (140–63 BCE) before Rome. Revolts in 66–73 and 132–135 CE ended in the Temple's destruction (70 CE) and mass expulsion.",
    religion: "Monotheism developed over centuries. The Hebrew Bible was compiled largely during and after the Babylonian exile. After 70 CE, Rabbinic Judaism replaced Temple sacrifice with study and prayer, producing the Mishnah (c. 200) and Talmud.",
    literature: "Genesis, Exodus, the Psalms, Job, Ecclesiastes, the Song of Songs — some of the most-read texts in history. The Dead Sea Scrolls (found 1947) include biblical manuscripts ~1,000 years older than previously known copies.",
    people: "David, Solomon, Isaiah, Jeremiah, Ezra, Herod the Great, Hillel, Jesus of Nazareth, Josephus, Rabbi Akiva, Bar Kokhba.",
    legacy: "The seven-day week with a day of rest, the Ten Commandments, prophets as social critics, and the Jewish diaspora's 2,000-year history. Hanukkah commemorates the Maccabean revolt (164 BCE).",
    fun: "Masada's defenders' mass suicide (73/74 CE) is known only from Josephus; Israeli army units once held swearing-in ceremonies there: 'Masada shall not fall again'.",
    debates: "The historicity of the Exodus and of a large united monarchy under David and Solomon is debated. The Tel Dan Stele (found 1993) mentions the 'House of David', supporting that a dynasty existed." } },
{ id: "sasanian", name: "Sasanian Persian Empire", start: 224, end: 651, lat: 33.09, lng: 44.58, r: 1100, reg: "me", ev: "documented", src: "Sasanian Empire",
  modern: "Iran, Iraq, Afghanistan, the Caucasus, Central Asia",
  sum: "The last pre-Islamic Persian empire, Rome's great rival for four centuries, with Zoroastrianism as state religion.",
  places: [["Ctesiphon", "near Salman Pak, Iraq", 33.09, 44.58], ["Naqsh-e Rostam", "near Persepolis, Iran", 29.99, 52.87]], rel: ["persia", "byzantine", "rome-emp", "umayyad"],
  s: { politics: "Shapur I captured the Roman emperor Valerian (260 CE) — carved in triumph at Naqsh-e Rostam. Exhausting wars with Byzantium (602–628) left both empires open to the Arab conquests.",
    religion: "Zoroastrian clergy compiled the Avesta. Also home to Manichaeism, Nestorian Christianity, and the Babylonian Talmud's academies.",
    science: "The Academy of Gondishapur fused Greek, Persian and Indian medicine.",
    legacy: "Persian court culture — polo, chess (shatranj), backgammon, the Shahnameh's heroes — passed into Islamic civilization. The Taq Kasra arch is still the largest unreinforced brick vault.",
    fun: "Persian 'chogan' is polo's ancestor; the British learned it in 19th-century Manipur, India." } },
{ id: "umayyad", name: "Umayyad Caliphate", start: 661, end: 750, lat: 33.51, lng: 36.29, r: 1700, reg: "me", ev: "documented", src: "Umayyad Caliphate",
  modern: "From Spain and Morocco to Pakistan and Uzbekistan",
  sum: "The first hereditary Islamic dynasty, ruling from Damascus over one of history's largest empires, from the Atlantic to the Indus.",
  places: [["Damascus", "Damascus, Syria", 33.51, 36.31], ["Dome of the Rock", "Jerusalem", 31.778, 35.235], ["Córdoba", "Spain (later Umayyad emirate/caliphate)", 37.88, -4.78]], rel: ["abbasid", "byzantine", "sasanian"],
  s: { politics: "Founded by Mu'awiya after the First Fitna (civil war). The killing of Husayn at Karbala (680) is central to the Sunni–Shia divide.",
    religion: "Arabic made the language of administration; coins with only text replaced images. The Dome of the Rock (691) is the oldest surviving major Islamic monument.",
    legacy: "The Shia commemoration of Ashura mourns Karbala. In Spain, the Umayyad Caliphate of Córdoba (929–1031) built the Great Mosque of Córdoba.",
    fun: "The Umayyad Mosque in Damascus houses a shrine said to hold the head of John the Baptist — revered by Muslims and Christians alike." } },
{ id: "safavid", name: "Safavid Iran", start: 1501, end: 1736, lat: 32.65, lng: 51.67, r: 800, reg: "me", ev: "documented", src: "Safavid Iran",
  modern: "Iran, Azerbaijan, parts of Iraq, Afghanistan",
  sum: "The dynasty that made Iran Shia — a decision that still defines the Middle East — and built Isfahan, 'half the world'.",
  places: [["Isfahan", "Isfahan, Iran", 32.65, 51.67], ["Tabriz", "Tabriz, Iran", 38.08, 46.29]], rel: ["ottoman", "mughal", "iran"],
  s: { religion: "Shah Ismail I imposed Twelver Shia Islam on a mostly Sunni population, creating the Sunni–Shia geopolitical fault line between Iran and its neighbors.",
    art: "Shah Abbas I's Naqsh-e Jahan Square in Isfahan; Persian carpets became a major export — 'Isfahan nesf-e jahan' (Isfahan is half the world).",
    legacy: "Iran's modern Shia identity; the Ottoman–Safavid border roughly matches today's Iran–Iraq and Iran–Turkey borders.",
    fun: "Shah Abbas moved thousands of Armenians to Isfahan to run the silk trade; the New Julfa Armenian quarter and its cathedral still stand." } },
{ id: "iran", name: "Modern Iran", start: 1925, end: 2025, lat: 35.69, lng: 51.39, r: 650, reg: "me", ev: "documented", src: "History of Iran",
  modern: "Islamic Republic of Iran",
  sum: "From the Pahlavi shahs to the 1979 Islamic Revolution — a country of 90 million with one of the world's oldest continuous cultures and a central role in today's geopolitics.",
  places: [["Tehran", "capital", 35.69, 51.39], ["Qom", "religious center", 34.64, 50.88], ["Natanz", "nuclear site", 33.72, 51.73]], rel: ["safavid", "persia", "sasanian"],
  s: { politics: "Reza Shah (1925) modernized forcibly. In 1953 a CIA/MI6-backed coup removed elected PM Mohammad Mosaddegh after he nationalized oil. The 1979 revolution created a theocratic republic under Ayatollah Khomeini; the US embassy hostage crisis lasted 444 days. Iran–Iraq War (1980–88).",
    society: "Highly educated: women outnumber men at universities in many years. The 2022 'Woman, Life, Freedom' protests followed Mahsa Amini's death in morality-police custody.",
    literature: "Persian poetry is part of daily life — Hafez's divan is used for fortune-telling (fal-e Hafez) and Rumi is one of the bestselling poets in the US.",
    food: "Saffron (Iran grows ~90% of the world's), pistachios, tahdig (crispy rice), kebab, Nowruz's haft-sin table.",
    legacy: "Nowruz, the Persian New Year at the spring equinox, is ~3,000 years old and celebrated by ~300 million people across Asia.",
    fun: "Iranian cinema is world-class: Asghar Farhadi's A Separation (2011) won the Oscar for Best Foreign Language Film.",
    debates: "Iran's nuclear program and its regional network of allied militias are central to current Middle East conflicts." } },
{ id: "turkey", name: "Republic of Turkey", start: 1923, end: 2025, lat: 39.93, lng: 32.86, r: 550, reg: "me", ev: "documented", src: "History of the Republic of Turkey",
  modern: "Turkey (Türkiye)",
  sum: "Built from the Ottoman ruins by Mustafa Kemal Atatürk as a secular nation-state — and a bridge between Europe and the Middle East.",
  places: [["Ankara", "capital", 39.93, 32.86], ["Istanbul", "largest city", 41.01, 28.98], ["Gallipoli", "Çanakkale Province", 40.23, 26.28]], rel: ["ottoman", "byzantine"],
  s: { politics: "Atatürk abolished the sultanate (1922) and caliphate (1924), switched Turkish from Arabic to Latin script (1928), gave women the vote (1934), and required surnames ('Atatürk' = father of the Turks). A NATO member since 1952.",
    society: "Population exchange with Greece (1923) moved ~1.5 million people by religion. Kurds (~15–20% of the population) have long sought cultural and political rights.",
    food: "Döner kebab (the modern vertical version was popularized in Berlin by Turkish immigrants), baklava, simit, Turkish coffee (UNESCO heritage), çay.",
    legacy: "Over 3 million Turkish-heritage people in Germany. Turkey hosts more refugees than any other country (mainly Syrians).",
    fun: "Gallipoli (1915) made Atatürk's name — and is also the founding myth of Australian and New Zealand national identity (ANZAC Day)." } },
{ id: "saudi", name: "Saudi Arabia & the Gulf States", start: 1932, end: 2025, lat: 24.71, lng: 46.68, r: 900, reg: "me", ev: "documented", src: "History of Saudi Arabia",
  modern: "Saudi Arabia, UAE, Qatar, Kuwait, Bahrain, Oman",
  sum: "Desert sheikhdoms transformed by oil into some of the world's richest states — and custodians of Islam's holiest cities.",
  places: [["Riyadh", "capital", 24.71, 46.68], ["Mecca", "holiest city in Islam", 21.42, 39.83], ["Dubai", "UAE", 25.2, 55.27], ["Dhahran", "first oil discovery (1938)", 26.29, 50.11]], rel: ["umayyad", "ottoman"],
  s: { origins: "The 1744 alliance between Muhammad ibn Saud and preacher Muhammad ibn Abd al-Wahhab still underpins the state. Ibn Saud unified the kingdom in 1932.",
    economy: "Oil discovered 1938. Saudi Aramco is one of the most profitable companies on Earth. The 1973 OPEC oil embargo quadrupled prices and reshaped the world economy.",
    politics: "The 1979 Grand Mosque seizure pushed the kingdom toward stricter religious rule; since 2017 Crown Prince Mohammed bin Salman allowed women to drive (2018), cinemas and concerts, while cracking down on dissent (journalist Jamal Khashoggi's murder, 2018).",
    legacy: "The Hajj draws ~2 million pilgrims a year. Dubai's Burj Khalifa (828 m) is the world's tallest building. Qatar hosted the 2022 FIFA World Cup.",
    fun: "Before oil, pearl diving was the Gulf's main industry — Japan's invention of cultured pearls in the 1920s crashed it." } },
{ id: "israel", name: "State of Israel", start: 1948, end: 2025, lat: 32.08, lng: 34.78, r: 120, reg: "me", ev: "documented", src: "History of Israel",
  modern: "Israel",
  sum: "A Jewish state founded in 1948 after the Holocaust and decades of Zionist immigration — a tech powerhouse at the center of one of the world's most contested conflicts.",
  places: [["Tel Aviv", "economic center", 32.08, 34.78], ["Jerusalem", "claimed capital; status disputed internationally", 31.78, 35.22], ["Haifa", "port, Technion university", 32.79, 34.99]],
  rel: ["israel-ancient", "palestine", "ottoman", "british"],
  s: { origins: "Modern political Zionism (Theodor Herzl, 1896) sought a Jewish homeland amid European antisemitism. Britain's Balfour Declaration (1917) supported a 'national home' in Ottoman-then-British Palestine. After the Holocaust, the UN voted to partition Palestine (1947).",
    politics: "Independence in May 1948 led to war with Arab states; ~700,000 Palestinians fled or were expelled (the Nakba). Wars in 1956, 1967 (Six-Day War: Israel took the West Bank, Gaza, East Jerusalem, Golan, Sinai), 1973. Peace treaties with Egypt (1979) and Jordan (1994); Abraham Accords (2020). The Hamas attack of 7 October 2023 and the Gaza war that followed caused tens of thousands of deaths.",
    society: "Jewish immigrants came from Europe, the Middle East and North Africa, Ethiopia and the former USSR. About 20% of citizens are Arab. Hebrew was revived as a spoken language — a unique case of a liturgical language becoming a mother tongue again.",
    science: "'Start-up nation': drip irrigation (Netafim), Waze, Mobileye, USB flash drive precursors, the Iron Dome missile defense system. Highest R&D spending as % of GDP in the world.",
    food: "Falafel, hummus, shakshuka, sabich — a shared Levantine heritage that is itself contested ('hummus wars').",
    legacy: "Eliezer Ben-Yehuda's modern Hebrew dictionary; kibbutz communal farms; one of the most-discussed states in world politics.",
    debates: "Almost everything is contested: borders, settlements in the West Bank (considered illegal under international law by most states; Israel disputes this), Jerusalem's status, refugees' right of return, and the framing of the 1948 war. Atlas presents multiple perspectives — read sources from different sides." } },
{ id: "palestine", name: "Palestinians & the Palestinian Territories", start: 1948, end: 2025, lat: 31.9, lng: 35.2, r: 60, reg: "me", ev: "documented", src: "Palestinians",
  modern: "West Bank, Gaza Strip, East Jerusalem; large diaspora in Jordan, Lebanon, Syria, Chile and beyond",
  sum: "An Arab people with deep roots in the land, whose national identity crystallized in the 20th century and whose quest for statehood remains unresolved.",
  places: [["Ramallah", "West Bank, seat of the Palestinian Authority", 31.9, 35.2], ["Gaza City", "Gaza Strip", 31.5, 34.47], ["Bethlehem", "West Bank", 31.7, 35.2], ["Jericho", "West Bank, one of the oldest cities on Earth", 31.87, 35.44]],
  rel: ["israel", "ottoman", "british"],
  s: { politics: "1948: the Nakba ('catastrophe') displaced ~700,000. Jordan ruled the West Bank and Egypt ruled Gaza until 1967, when Israel occupied both. The PLO (Yasser Arafat) led the national movement; the Oslo Accords (1993) created the Palestinian Authority. Hamas took over Gaza in 2007. The State of Palestine is recognized by a large majority of UN members.",
    society: "Around 14 million Palestinians worldwide; about half live in the diaspora. UNRWA has served Palestinian refugees since 1949.",
    food: "Musakhan (national dish), maqluba, za'atar, knafeh from Nablus; olive harvests are central to rural culture.",
    literature: "Mahmoud Darwish is the national poet ('Identity Card'); Edward Said's Orientalism (1978) reshaped academic study of the 'East'.",
    legacy: "The keffiyeh became an international political symbol. Jericho is often called the world's oldest continuously inhabited city (~11,000 years).",
    debates: "Terminology, history and the path to peace (two states, one state, other options) are bitterly disputed. Atlas encourages reading Palestinian, Israeli and international sources." } },
{ id: "egypt-modern", name: "Modern Egypt", start: 1805, end: 2025, lat: 30.04, lng: 31.24, r: 500, reg: "af", ev: "documented", src: "History of modern Egypt",
  modern: "Egypt",
  sum: "From Muhammad Ali's modernization to Nasser, the Suez Crisis and the Arab Spring — the most populous Arab country and a cultural capital of the Arab world.",
  places: [["Cairo", "capital (~22 million metro)", 30.04, 31.24], ["Suez Canal", "Ismailia", 30.6, 32.3], ["Tahrir Square", "Cairo (2011 revolution)", 30.044, 31.236]], rel: ["egypt", "ottoman", "british"],
  s: { politics: "Muhammad Ali (r. 1805–48) built a modern army and cotton economy. British control from 1882. Nasser's 1952 revolution; nationalizing the Suez Canal triggered the 1956 Suez Crisis, a humiliation for Britain and France. Peace with Israel 1979 (Sadat, assassinated 1981). 2011 revolution toppled Mubarak; military returned in 2013.",
    literature: "Naguib Mahfouz won the Nobel Prize in 1988 (Cairo Trilogy). Umm Kulthum's concerts emptied streets across the Arab world.",
    food: "Koshari (lentils, rice, pasta, tomato sauce), ful medames, ta'ameya (Egyptian falafel made with fava beans).",
    fun: "Egyptian Arabic is the most widely understood Arabic dialect, thanks to Cairo's film and TV industry ('Hollywood of the Arab world')." } },

// ---------------- EUROPE ----------------
{ id: "france", name: "France", start: 987, end: 2025, lat: 46.6, lng: 2.4, r: 450, reg: "eu", ev: "documented", src: "History of France",
  modern: "France",
  sum: "From Capetian kings to Louis XIV, the Revolution, Napoleon and the Fifth Republic — a country that exported ideas (rights, the metric system, cuisine) to the world.",
  places: [["Paris", "capital", 48.86, 2.35], ["Versailles", "royal palace", 48.8, 2.12], ["Normandy beaches", "D-Day, 1944", 49.37, -0.88]], rel: ["rome-emp", "british", "germany"],
  s: { politics: "Louis XIV ('L'État, c'est moi' — probably apocryphal) centralized power at Versailles. 1789: Revolution, Declaration of the Rights of Man; the Terror; Napoleon's empire and Code civil (1804), still the basis of law in dozens of countries. Colonial empire in Africa, Indochina, the Caribbean.",
    ideas: "Descartes ('I think, therefore I am'), Voltaire, Rousseau, Montesquieu (separation of powers), Simone de Beauvoir (The Second Sex), Sartre, Camus, Foucault.",
    science: "Pasteur (germ theory, pasteurization), Marie Curie (Polish-French; two Nobel Prizes), the Lumière brothers (cinema), Braille, the metric system.",
    food: "Haute cuisine codified by Escoffier; the restaurant itself was popularized in Paris around the Revolution. The French gastronomic meal is UNESCO heritage. Baguette (UNESCO 2022).",
    literature: "Molière, Victor Hugo (Les Misérables), Dumas (The Three Musketeers), Proust, Jules Verne.",
    legacy: "French was the language of diplomacy for centuries — 'RSVP', 'déjà vu', 'entrepreneur'. Bastille Day (14 July). The Statue of Liberty was a French gift.",
    fun: "The Eiffel Tower (1889) was meant to be temporary and hated by artists; it survived because it was useful as a radio antenna." } },
{ id: "spain", name: "Spain & the Spanish Empire", start: 1479, end: 2025, lat: 40.42, lng: -3.7, r: 450, reg: "eu", ev: "documented", src: "History of Spain",
  modern: "Spain; former empire across the Americas, Philippines, parts of Africa",
  sum: "United by Ferdinand and Isabella, Spain built the first global empire — then endured decline, civil war and dictatorship before becoming a modern democracy.",
  places: [["Madrid", "capital", 40.42, -3.7], ["Granada", "Alhambra; last Muslim kingdom fell 1492", 37.18, -3.59], ["Seville", "gateway to the Americas", 37.39, -5.98]], rel: ["umayyad", "aztec", "inca", "mex"],
  s: { politics: "1492: fall of Granada, expulsion of Jews, Columbus's voyage. The Habsburg empire under Charles V and Philip II spanned Europe and the Americas. Civil War (1936–39) — a prelude to WWII — then Franco's dictatorship until 1975; peaceful transition to democracy.",
    religion: "The Spanish Inquisition (1478–1834) targeted converted Jews and Muslims; Muslims (Moriscos) were expelled in 1609–14.",
    literature: "Cervantes's Don Quixote (1605) — often called the first modern novel. García Lorca, killed in the Civil War.",
    art: "Velázquez, Goya, Picasso (Guernica, 1937), Dalí, Gaudí's Sagrada Família (under construction since 1882).",
    food: "Tapas, paella (Valencia), jamón ibérico, chocolate brought from Mexico. The Spanish introduced cattle, wheat and pigs to the Americas.",
    legacy: "Spanish is the world's second-most spoken native language (~500 million). The 'Spanish dollar' (piece of eight) was the first global currency — the $ sign likely derives from it.",
    fun: "Spain is in the 'wrong' time zone: Franco moved it to Central European Time in 1940 to match Nazi Germany — one reason Spaniards eat dinner so late." } },
{ id: "germany", name: "Holy Roman Empire & Germany", start: 962, end: 2025, lat: 51.17, lng: 10.45, r: 400, reg: "eu", ev: "documented", src: "History of Germany",
  modern: "Germany, Austria, and historically Czechia, northern Italy, the Low Countries",
  sum: "A patchwork of hundreds of states unified only in 1871 — home of the printing press, the Reformation, Bach, Kant, and the Holocaust — and today Europe's largest economy.",
  places: [["Berlin", "capital", 52.52, 13.4], ["Wittenberg", "Reformation", 51.87, 12.65], ["Auschwitz", "Oświęcim, Poland (Nazi death camp)", 50.03, 19.2]], rel: ["rome-emp", "france", "poland"],
  s: { politics: "Holy Roman Empire (962–1806); the Thirty Years' War (1618–48) killed perhaps a third of Germans in some regions. Bismarck unified Germany (1871). Defeat in WWI, the Weimar Republic, hyperinflation (1923), Hitler's dictatorship (1933–45), the Holocaust murdered six million Jews. Divided 1949–1990; reunified 3 October 1990.",
    ideas: "Kant, Hegel, Marx, Nietzsche, Weber, Arendt; the Frankfurt School.",
    science: "Gutenberg, Kepler, Einstein, Planck, Benz's automobile (1886), Diesel, aspirin (Bayer, 1899), the jet engine (contested with Britain).",
    literature: "Goethe (Faust), Schiller, the Brothers Grimm's fairy tales (1812), Kafka (Prague, German-language), Thomas Mann.",
    food: "Beer purity law (Reinheitsgebot, 1516), bratwurst, pretzels, Christmas markets, the Christmas tree custom itself.",
    legacy: "Vergangenheitsbewältigung — 'working through the past' — Germany's model of confronting the Holocaust is studied worldwide. Kindergarten is a German word and idea (Fröbel, 1837).",
    fun: "Hamburgers and frankfurters are named after Hamburg and Frankfurt; 'Gesundheit', 'angst', 'zeitgeist' and 'wanderlust' are German loans." } },
{ id: "italy-ren", name: "Renaissance Italy & Modern Italy", start: 1300, end: 2025, lat: 43.77, lng: 11.25, r: 380, reg: "eu", ev: "documented", src: "Italian Renaissance",
  modern: "Italy",
  sum: "Rival city-states — Florence, Venice, Milan, Rome — financed the Renaissance; Italy unified only in 1861 and gave the world banking, opera, and much of its art.",
  places: [["Florence", "Renaissance center", 43.77, 11.25], ["Venice", "maritime republic", 45.44, 12.33], ["Rome", "papacy; capital since 1871", 41.9, 12.5]], rel: ["rome-emp", "byzantine", "ottoman"],
  s: { economy: "The Medici bank, double-entry bookkeeping (Luca Pacioli, 1494), bills of exchange — 'bank' comes from banca (bench), 'bankrupt' from banca rotta.",
    art: "Giotto, Brunelleschi's dome, Botticelli, Leonardo, Michelangelo (Sistine Chapel, David), Raphael, Titian.",
    ideas: "Petrarch and humanism; Machiavelli's The Prince (1532); Galileo, tried by the Inquisition in 1633.",
    politics: "Garibaldi and Cavour unified Italy (Risorgimento, 1861). Mussolini's Fascism (1922–43) — the word 'fascism' is Italian. Republic since 1946.",
    food: "Pasta (dried pasta documented in Sicily by 1154 by al-Idrisi), pizza, espresso (machines c. 1900s), gelato, risotto — most built on New World tomatoes and corn (polenta).",
    legacy: "Musical terms are Italian (piano, forte, allegro) because opera and notation developed there. 'Quarantine', 'ghetto' (Venice, 1516) and 'gazette' are Venetian.",
    fun: "Venice's Arsenale could build a galley in a single day using assembly-line methods — centuries before Ford." } },
{ id: "russia", name: "Kievan Rus' & Tsarist Russia", start: 882, end: 1917, lat: 56.0, lng: 40.0, r: 1500, reg: "eu", ev: "documented", src: "History of Russia",
  modern: "Russia, Ukraine, Belarus (Rus' heritage); the Russian Empire also spanned Finland, Poland, the Caucasus, Central Asia",
  sum: "From Norse-founded Kyiv to Ivan the Terrible, Peter the Great, Catherine the Great and the last Tsar — an empire that grew to cover a sixth of Earth's land.",
  places: [["Kyiv", "capital of Kievan Rus'", 50.45, 30.52], ["Moscow", "Grand Duchy, then capital", 55.75, 37.62], ["St Petersburg", "Peter's 'window to Europe' (1703)", 59.94, 30.31]], rel: ["vikings", "byzantine", "mongol", "ussr", "ukraine"],
  s: { religion: "Vladimir of Kyiv adopted Orthodox Christianity from Byzantium in 988 — legend says he rejected Islam because 'drinking is the joy of the Rus''.",
    politics: "Mongol rule (1240–1480). Ivan IV first crowned Tsar (1547). Peter the Great westernized; Catherine the Great expanded to the Black Sea. Serfdom abolished in 1861 — two years before US emancipation. Revolution in 1917; the royal family was executed in 1918.",
    literature: "Pushkin, Gogol, Tolstoy (War and Peace), Dostoevsky (Crime and Punishment), Chekhov.",
    art: "Tchaikovsky (Swan Lake, The Nutcracker), Fabergé eggs, onion domes (St Basil's).",
    food: "Borscht (claimed by Ukraine; Ukrainian borscht culture is UNESCO heritage since 2022), pelmeni, blini, vodka.",
    legacy: "Alaska was Russian until 1867. Russia's expansion into Siberia reached the Pacific by 1639 — earlier than the US reached its Pacific coast.",
    fun: "Napoleon's 1812 invasion (inspiration for Tchaikovsky's 1812 Overture, with real cannons) lost ~400,000+ men largely to cold, typhus and hunger." } },
{ id: "russia-fed", name: "Russian Federation", start: 1991, end: 2025, lat: 55.75, lng: 60.0, r: 1800, reg: "eu", ev: "documented", src: "History of Russia (1991–present)",
  modern: "Russia",
  sum: "The largest country on Earth, rebuilt from the Soviet collapse through 1990s chaos into Putin's centralized state.",
  places: [["Moscow", "capital", 55.75, 37.62], ["Crimea", "annexed from Ukraine 2014", 44.95, 34.1]], rel: ["ussr", "russia", "ukraine"],
  s: { politics: "Yeltsin's 1990s: 'shock therapy', loans-for-shares privatization creating the oligarchs, the 1998 default, wars in Chechnya. Putin since 2000; annexation of Crimea (2014); full-scale invasion of Ukraine (2022).",
    economy: "Oil and gas exports dominate. Western sanctions after 2022 reshaped trade toward China and India.",
    legacy: "11 time zones; Lake Baikal; the world's largest nuclear arsenal." } },
{ id: "ukraine", name: "Ukraine", start: 1991, end: 2025, lat: 49.0, lng: 31.5, r: 450, reg: "eu", ev: "documented", src: "History of Ukraine",
  modern: "Ukraine",
  sum: "Heir to Kievan Rus' and the Cossack Hetmanate, independent since 1991 — and since 2014/2022 fighting for its survival against Russian invasion.",
  places: [["Kyiv", "capital", 50.45, 30.52], ["Chernobyl", "1986 nuclear disaster", 51.39, 30.1], ["Odesa", "Black Sea port", 46.48, 30.72], ["Kharkiv", "second city", 49.99, 36.23]], rel: ["russia", "ussr", "russia-fed", "vikings"],
  s: { origins: "Kyiv was the capital of Rus' a millennium ago. Zaporozhian Cossacks (16th–18th c.) became a national symbol. Divided between Russian and Austro-Hungarian empires; the Holodomor famine (1932–33) killed millions under Stalin.",
    politics: "Independence 1991 (90% voted yes). Orange Revolution (2004), Euromaidan (2014). Russia annexed Crimea and backed separatists in Donbas (2014), then launched a full-scale invasion on 24 February 2022.",
    food: "Borscht, varenyky, salo, paska bread. Ukraine is one of the world's largest grain exporters — 'breadbasket of Europe' — vital for Africa and the Middle East.",
    legacy: "Nobel-winning-era writers and figures with Ukrainian roots include Gogol, Bulgakov and Golda Meir (born in Kyiv). The flag's blue-over-yellow evokes sky over wheat fields.",
    fun: "The world's largest airplane, the Antonov An-225 'Mriya' (dream), was Ukrainian; it was destroyed at Hostomel airport in 2022." } },
{ id: "poland", name: "Poland", start: 966, end: 2025, lat: 52.23, lng: 21.01, r: 320, reg: "eu", ev: "documented", src: "History of Poland",
  modern: "Poland (historically also Lithuania, Belarus, western Ukraine)",
  sum: "Once Europe's largest state (the Polish–Lithuanian Commonwealth), erased from the map for 123 years, devastated in WWII, and now one of Europe's fastest-growing economies.",
  places: [["Kraków", "royal capital", 50.06, 19.94], ["Warsaw", "capital", 52.23, 21.01], ["Gdańsk", "Solidarity movement (1980)", 54.35, 18.65]], rel: ["germany", "russia", "ussr"],
  s: { politics: "The Commonwealth (1569–1795) had an elected king and a parliament where any noble could veto (liberum veto). Its 1791 constitution was Europe's first modern written one. Partitioned by Russia, Prussia and Austria (1795–1918). WWII: invaded by Germany and the USSR; ~6 million Polish citizens died, half of them Jews. Solidarity trade union (Lech Wałęsa) helped end communism in 1989.",
    people: "Copernicus, Marie Skłodowska-Curie, Chopin, Pope John Paul II, Wisława Szymborska.",
    food: "Pierogi, bigos, pączki; the bagel likely originated in Kraków (first mentioned 1610).",
    fun: "The first Enigma code breaks were made by Polish mathematicians (Rejewski, Różycki, Zygalski) in 1932 — they handed their work to Britain in 1939." } },
{ id: "netherlands", name: "Dutch Republic & the Netherlands", start: 1581, end: 2025, lat: 52.37, lng: 4.9, r: 160, reg: "eu", ev: "documented", src: "History of the Netherlands",
  modern: "Netherlands; former colonies Indonesia, Suriname, Caribbean islands",
  sum: "A small, partly below-sea-level republic that invented the modern stock market, dominated 17th-century trade, and painted its Golden Age.",
  places: [["Amsterdam", "capital", 52.37, 4.9], ["Delft", "Vermeer's home", 52.01, 4.36]], rel: ["spain", "british", "idn"],
  s: { economy: "The VOC (1602) issued the first publicly traded shares; Amsterdam had the first modern stock exchange. Tulip mania (1637). Wealth from the spice monopoly in Indonesia, built on violence.",
    art: "Rembrandt, Vermeer, Frans Hals; later Van Gogh and Mondrian.",
    science: "Leeuwenhoek's microscopes discovered bacteria (1676); Huygens's pendulum clock.",
    legacy: "New York was New Amsterdam: 'cookie', 'boss', 'Yankee' (maybe from Jan Kees), Brooklyn (Breukelen) and Harlem (Haarlem) are Dutch. Dikes and water management export worldwide.",
    fun: "About a quarter of the Netherlands is below sea level; 'God created the world, but the Dutch created the Netherlands'." } },
{ id: "balkans", name: "Yugoslavia & the Balkans", start: 1918, end: 2025, lat: 44.0, lng: 19.5, r: 380, reg: "eu", ev: "documented", src: "Yugoslavia",
  modern: "Serbia, Croatia, Bosnia and Herzegovina, Slovenia, Montenegro, North Macedonia, Kosovo",
  sum: "South Slav peoples unified after WWI, held together by Tito's non-aligned communism, and torn apart by the wars of the 1990s.",
  places: [["Belgrade", "Serbia", 44.79, 20.45], ["Sarajevo", "Bosnia and Herzegovina", 43.86, 18.41], ["Srebrenica", "1995 genocide", 44.1, 19.3], ["Dubrovnik", "Croatia", 42.65, 18.09]], rel: ["ottoman", "byzantine"],
  s: { politics: "Tito broke with Stalin (1948) and co-founded the Non-Aligned Movement. After his death (1980), nationalism rose; the 1991–2001 wars killed ~130,000. The Srebrenica massacre (1995) of ~8,000 Bosniak men and boys was ruled genocide by international courts.",
    religion: "Orthodox Serbs, Catholic Croats, Muslim Bosniaks speak mutually intelligible languages — religion and history, more than language, define the divisions.",
    legacy: "'Balkanization' entered English for fragmentation. Croatia joined the EU in 2013. The 1914 Sarajevo assassination started WWI.",
    fun: "Game of Thrones filmed King's Landing in Dubrovnik, triggering a tourism boom." } },

// ---------------- SOUTH & CENTRAL ASIA ----------------
{ id: "kushan", name: "Kushan Empire", start: 30, end: 375, lat: 34.0, lng: 71.5, r: 800, reg: "sa", ev: "mixed", src: "Kushan Empire",
  modern: "Afghanistan, Pakistan, northern India, Tajikistan, Uzbekistan",
  sum: "A Central Asian empire at the crossroads of the Silk Roads that blended Greek, Persian, Indian and Chinese culture and helped carry Buddhism to China.",
  places: [["Peshawar", "Pakistan (capital Purushapura)", 34.01, 71.58], ["Mathura", "India", 27.49, 77.67], ["Bagram", "Afghanistan (Begram treasure)", 34.96, 69.26]], rel: ["han", "rome-emp", "maurya", "gupta"],
  s: { religion: "Kanishka (2nd c.) hosted a Buddhist council; Mahayana Buddhism spread from Kushan lands to China.",
    art: "Gandhara and Mathura schools created the first Buddha images.",
    fun: "The Begram hoard in Afghanistan held Roman glass, Indian ivories and Chinese lacquer in one room — the Silk Road in miniature." } },
{ id: "chola", name: "Chola Empire", start: 848, end: 1279, lat: 10.78, lng: 79.13, r: 550, reg: "sa", ev: "documented", src: "Chola dynasty",
  modern: "Tamil Nadu (India), Sri Lanka; naval reach to Malaysia and Indonesia",
  sum: "A Tamil maritime empire whose navy raided Srivijaya in Southeast Asia and whose bronze sculptures and temples are masterpieces of Indian art.",
  places: [["Thanjavur", "Tamil Nadu, India", 10.78, 79.13], ["Gangaikonda Cholapuram", "Tamil Nadu", 11.21, 79.45]], rel: ["srivijaya", "gupta", "srilanka"],
  s: { politics: "Rajaraja I and Rajendra I (r. 1014–44) conquered Sri Lanka and launched a naval expedition against Srivijaya (1025).",
    art: "The Brihadisvara Temple (1010) and bronze Nataraja (dancing Shiva) — a Nataraja statue stands at CERN, a gift from India, symbolizing the cosmic dance of subatomic particles.",
    literature: "Tamil is one of the oldest living classical languages; the Sangam poems are ~2,000 years old.",
    legacy: "Tamil diaspora and temple architecture across Southeast Asia." } },
{ id: "delhi", name: "Delhi Sultanate", start: 1206, end: 1526, lat: 28.61, lng: 77.21, r: 750, reg: "sa", ev: "documented", src: "Delhi Sultanate",
  modern: "Northern India, Pakistan, Bangladesh",
  sum: "Five Turkic and Afghan dynasties ruling from Delhi that repelled Mongol invasions and fused Persian and Indian culture.",
  places: [["Qutub Minar", "Delhi", 28.52, 77.19], ["Delhi", "India", 28.61, 77.21]], rel: ["mughal", "mongol", "vijayanagara"],
  s: { politics: "Razia Sultana (r. 1236–40) — one of few women to rule in medieval Islamic India. Alauddin Khalji repelled Mongol invasions. Timur sacked Delhi in 1398.",
    art: "Indo-Islamic architecture: the Qutub Minar (begun 1199), tallest brick minaret in the world.",
    language: "Amir Khusrau, poet and musician, is credited (traditionally) with shaping Hindustani/Urdu, qawwali and the sitar (debated).",
    legacy: "Sufi orders (Chishti — Nizamuddin's shrine in Delhi) shaped South Asian Islam." } },
{ id: "vijayanagara", name: "Vijayanagara Empire", start: 1336, end: 1646, lat: 15.33, lng: 76.46, r: 450, reg: "sa", ev: "documented", src: "Vijayanagara Empire",
  modern: "Karnataka, Andhra Pradesh, Tamil Nadu (India)",
  sum: "A South Indian Hindu empire whose capital at Hampi was one of the world's largest and richest cities around 1500.",
  places: [["Hampi", "Karnataka, India", 15.33, 76.46]], rel: ["delhi", "mughal", "chola"],
  s: { economy: "Persian and Portuguese visitors described bazaars of diamonds and horses; Hampi may have had ~500,000 people.",
    art: "Hampi's ruins (UNESCO) include the stone chariot at Vittala Temple — on India's 50-rupee note.",
    legacy: "Carnatic classical music flourished under its patronage (Purandara Dasa, 'father of Carnatic music').",
    fun: "Defeated at Talikota (1565); Hampi was looted for months and never recovered." } },
{ id: "timurid", name: "Timurid Empire", start: 1370, end: 1507, lat: 39.65, lng: 66.96, r: 1000, reg: "sa", ev: "documented", src: "Timurid Empire",
  modern: "Uzbekistan, Iran, Afghanistan, Turkmenistan",
  sum: "Timur (Tamerlane) built a brutal steppe empire; his descendants made Samarkand and Herat jewels of Persian art and science — and founded the Mughal dynasty.",
  places: [["Samarkand", "Uzbekistan (Registan)", 39.65, 66.96], ["Herat", "Afghanistan", 34.35, 62.2]], rel: ["mongol", "mughal", "ottoman"],
  s: { science: "Ulugh Beg's observatory (1420s) produced the most accurate star catalog since Ptolemy.",
    art: "Turquoise-domed architecture of the Registan and Gur-e-Amir (Timur's tomb).",
    legacy: "Babur, founder of the Mughals, was a Timurid. Uzbekistan treats Timur as a national hero.",
    fun: "Legend: a curse warned against opening Timur's tomb; Soviet scientists opened it on 20 June 1941 — two days before Germany invaded the USSR." } },
{ id: "maratha", name: "Maratha Empire", start: 1674, end: 1818, lat: 18.52, lng: 73.86, r: 650, reg: "sa", ev: "documented", src: "Maratha Confederacy",
  modern: "Maharashtra and much of central and northern India",
  sum: "Founded by Shivaji, the Marathas broke Mughal power and dominated 18th-century India until defeated by the British.",
  places: [["Raigad Fort", "Maharashtra", 18.23, 73.44], ["Pune", "Peshwa capital", 18.52, 73.86]], rel: ["mughal", "british"],
  s: { politics: "Shivaji (crowned 1674) used guerrilla warfare and hill forts; a navy defended the Konkan coast. Defeated by Afghans at Panipat (1761) and by Britain in three Anglo-Maratha wars.",
    legacy: "Shivaji is a major icon in Maharashtra; Mumbai's airport and main railway station are named after him." } },
{ id: "pakistan", name: "Pakistan", start: 1947, end: 2025, lat: 30.38, lng: 69.35, r: 600, reg: "sa", ev: "documented", src: "History of Pakistan",
  modern: "Pakistan",
  sum: "Created at Partition as a homeland for South Asia's Muslims; today the world's fifth most populous country and a nuclear power.",
  places: [["Islamabad", "capital", 33.68, 73.05], ["Karachi", "largest city", 24.86, 67.0], ["Lahore", "cultural capital", 31.55, 74.34], ["Mohenjo-daro", "Indus heritage", 27.33, 68.14]],
  rel: ["indus", "mughal", "british", "india", "bangladesh"],
  s: { politics: "Muhammad Ali Jinnah led the Pakistan movement. East Pakistan seceded as Bangladesh in 1971. Long periods of military rule; wars with India over Kashmir.",
    people: "Malala Yousafzai (youngest Nobel laureate, 2014), Benazir Bhutto (first woman to lead a Muslim-majority democracy), Nusrat Fateh Ali Khan, Abdus Salam (Nobel physics).",
    food: "Biryani, nihari, karahi, chapli kebab; mangoes are a national passion.",
    legacy: "Urdu poetry (Iqbal, Faiz); cricket — Imran Khan captained the 1992 World Cup win before becoming PM.",
    fun: "K2, the world's second-highest and arguably deadliest mountain, is on the Pakistan–China border." } },
{ id: "bangladesh", name: "Bangladesh", start: 1971, end: 2025, lat: 23.81, lng: 90.41, r: 220, reg: "sa", ev: "documented", src: "History of Bangladesh",
  modern: "Bangladesh",
  sum: "Born in a 1971 war of independence fought partly over language, Bangladesh became one of the world's most densely populated countries and a garment-making giant.",
  places: [["Dhaka", "capital", 23.81, 90.41], ["Sundarbans", "largest mangrove forest", 21.95, 89.18]], rel: ["pakistan", "india", "british"],
  s: { politics: "The 1952 Bengali Language Movement — protesters killed for demanding Bengali as an official language — is commemorated by UNESCO's International Mother Language Day (21 Feb). Independence after a 1971 war with mass atrocities.",
    economy: "Second-largest garment exporter. The Rana Plaza collapse (2013) killed 1,134 workers. Muhammad Yunus's Grameen Bank pioneered microcredit (Nobel 2006).",
    literature: "Rabindranath Tagore (Bengali, Nobel 1913) wrote the national anthems of both Bangladesh and India.",
    fun: "Bangladesh's population (~170 million) lives in an area smaller than Illinois or England plus Wales." } },
{ id: "srilanka", name: "Sri Lanka", start: -377, end: 2025, lat: 7.87, lng: 80.77, r: 160, reg: "sa", ev: "documented", src: "History of Sri Lanka",
  modern: "Sri Lanka",
  sum: "An island civilization with 2,300 years of recorded chronicles, Theravada Buddhism, and a colonial history under the Portuguese, Dutch and British.",
  places: [["Anuradhapura", "ancient capital", 8.35, 80.39], ["Sigiriya", "rock fortress", 7.96, 80.76], ["Kandy", "Temple of the Tooth", 7.29, 80.64]], rel: ["maurya", "chola", "british"],
  s: { religion: "The Mahavamsa chronicle (6th c.) records Buddhism's arrival under Ashoka. The Pali Canon was first written down here (c. 29 BCE).",
    politics: "Independence 1948 as Ceylon. A civil war (1983–2009) between the government and the Tamil Tigers killed tens of thousands. Economic collapse and protests in 2022.",
    food: "Ceylon tea (Britain planted it after coffee rust destroyed coffee in the 1870s); cinnamon is native here.",
    fun: "'Serendipity' comes from Serendip, an old name for Sri Lanka — from a Persian tale of three princes who kept making happy discoveries." } },
{ id: "afghanistan", name: "Afghanistan", start: 1747, end: 2025, lat: 34.53, lng: 69.17, r: 420, reg: "sa", ev: "documented", src: "History of Afghanistan",
  modern: "Afghanistan",
  sum: "The 'graveyard of empires' at the heart of Asia's trade routes — from the Durrani Empire to the Great Game, Soviet war, US intervention and Taliban rule.",
  places: [["Kabul", "capital", 34.53, 69.17], ["Bamiyan", "giant Buddhas (destroyed 2001)", 34.83, 67.83], ["Kandahar", "south", 31.63, 65.71]], rel: ["kushan", "timurid", "mughal", "british", "ussr"],
  s: { politics: "Ahmad Shah Durrani founded modern Afghanistan (1747). Britain and Russia's 'Great Game' made it a buffer state; Britain's 1842 retreat from Kabul was a disaster. Soviet invasion (1979–89), civil war, Taliban (1996–2001), US-led war (2001–2021), Taliban return (2021).",
    art: "The Bamiyan Buddhas (6th c., 55 m tall) were dynamited by the Taliban in 2001.",
    food: "Kabuli pulao, mantu, bolani; pomegranates from Kandahar.",
    fun: "Afghanistan's lapis lazuli mines at Sar-e Sang have supplied the blue stone for 6,000+ years — including for Tutankhamun's mask." } },

// ---------------- EAST ASIA ----------------
{ id: "korea-3k", name: "Three Kingdoms & Silla Korea", start: -57, end: 935, lat: 35.84, lng: 129.21, r: 320, reg: "ea", ev: "mixed", src: "Three Kingdoms of Korea",
  modern: "North and South Korea, parts of northeast China",
  sum: "Goguryeo, Baekje and Silla competed for the peninsula until Silla unified most of it (668), creating a Buddhist golden age centered on Gyeongju.",
  places: [["Gyeongju", "Silla capital, South Korea", 35.84, 129.21], ["Buyeo", "Baekje capital, South Korea", 36.28, 126.91], ["Pyongyang", "Goguryeo capital (from 427)", 39.03, 125.75]],
  rel: ["han", "tang", "heian", "goryeo"],
  s: { politics: "Goguryeo repelled massive Sui and Tang invasions. Silla allied with Tang China to defeat Baekje (660) and Goguryeo (668), then expelled the Tang.",
    religion: "Buddhism arrived in 372; Baekje transmitted it to Japan. Bulguksa temple and the Seokguram grotto Buddha (8th c.) are UNESCO sites.",
    science: "Cheomseongdae (7th c.) in Gyeongju may be East Asia's oldest surviving observatory. Silla goldsmiths made spectacular crowns.",
    society: "Silla's 'bone rank' system fixed people's status by birth. The Hwarang were elite youth warriors — a K-drama subject.",
    legacy: "The name 'Korea' comes from Goguryeo via Goryeo.",
    fun: "Silla had three reigning queens, including Queen Seondeok (r. 632–647), who commissioned Cheomseongdae." } },
{ id: "goryeo", name: "Goryeo Korea", start: 918, end: 1392, lat: 37.97, lng: 126.55, r: 320, reg: "ea", ev: "documented", src: "Goryeo",
  modern: "Korea",
  sum: "The dynasty that gave Korea its name — celadon pottery, the Tripitaka Koreana, and the world's oldest surviving book printed with movable metal type.",
  places: [["Kaesong", "North Korea", 37.97, 126.55], ["Haeinsa Temple", "South Korea (Tripitaka Koreana)", 35.8, 128.1]], rel: ["korea-3k", "joseon", "mongol", "song"],
  s: { science: "Jikji (1377), a Buddhist text, is the oldest extant book printed with movable metal type — 78 years before Gutenberg's Bible. Its only surviving volume is in the National Library of France.",
    religion: "The Tripitaka Koreana: 81,258 woodblocks carved (1237–1248) as a prayer for protection against Mongol invasion; still stored at Haeinsa.",
    art: "Goryeo celadon, with its jade-green glaze and inlay technique, was prized even by the Chinese.",
    politics: "Mongol invasions forced vassalage to the Yuan; Korean princes married Mongol princesses." } },
{ id: "joseon", name: "Joseon Korea", start: 1392, end: 1897, lat: 37.57, lng: 126.98, r: 320, reg: "ea", ev: "documented", src: "Joseon",
  modern: "North and South Korea",
  sum: "One of history's longest-ruling dynasties (500 years): a Neo-Confucian state that invented the Korean alphabet and repelled Japanese invasion with 'turtle ships'.",
  places: [["Seoul (Hanyang)", "capital", 37.57, 126.98], ["Gyeongbokgung Palace", "Seoul", 37.58, 126.98], ["Myeongnyang Strait", "Admiral Yi's 1597 victory", 34.57, 126.31]],
  rel: ["goryeo", "ming", "qing", "japan-shogun", "south-korea", "north-korea"],
  s: { language: "King Sejong the Great promulgated Hangul in 1446 so ordinary people could read — 24 letters designed to mirror the shape of the mouth when speaking. Linguists praise it as one of the most scientific writing systems. Hangul Day (9 Oct) is a national holiday.",
    ideas: "Neo-Confucianism shaped family rites, education, civil-service exams and the yangban aristocracy. Respect for elders and ancestral rites (jesa) persist.",
    politics: "Japan's invasions (1592–98) were defeated with Ming help and Admiral Yi Sun-sin's navy, which won at Myeongnyang with 13 ships against 130+. Later called the 'Hermit Kingdom' for its isolation; annexed by Japan in 1910.",
    science: "Sejong's era produced rain gauges (1441, among the world's first standardized ones), water clocks and sundials.",
    food: "Kimchi (red chili kimchi only after chilies arrived c. 1600), bibimbap, royal court cuisine.",
    legacy: "Joseon-era settings dominate K-dramas (Kingdom, Jewel in the Palace). The hanbok and the gat hat.",
    fun: "The turtle ship (geobukseon) had spikes on its roof to stop boarders — an image now on Korean currency and in museums worldwide." } },
{ id: "south-korea", name: "South Korea", start: 1948, end: 2025, lat: 37.57, lng: 127.5, r: 200, reg: "ea", ev: "documented", src: "History of South Korea",
  modern: "Republic of Korea",
  sum: "From one of the world's poorest countries after the Korean War to a tech and cultural superpower — Samsung, K-pop, K-dramas — in two generations.",
  places: [["Seoul", "capital (~26 million metro)", 37.57, 126.98], ["Busan", "port city", 35.18, 129.08], ["Gwangju", "1980 uprising", 35.16, 126.85], ["Panmunjom", "DMZ truce village", 37.96, 126.68]],
  rel: ["joseon", "north-korea", "japan"],
  s: { politics: "Division at the 38th parallel (1945); Korean War (1950–53) ended in an armistice, not a peace treaty. Authoritarian rule under Syngman Rhee and Park Chung-hee; the Gwangju Uprising (1980); democracy from 1987. In 2024 President Yoon briefly declared martial law; parliament overturned it within hours and he was impeached.",
    economy: "The 'Miracle on the Han River': chaebol conglomerates (Samsung, Hyundai, LG, SK) — GDP per capita rose from below many African countries' in 1960 to above Japan's (by some measures) in the 2020s.",
    society: "Among the world's lowest fertility rates (~0.7). Extremely competitive education; the suneung exam day delays flights so planes don't disturb test-takers.",
    food: "Kimchi, Korean BBQ, tteokbokki, fried chicken ('chimaek' = chicken + beer), ramyeon; Koreans eat the most instant noodles per capita.",
    legacy: "The 'Korean Wave' (Hallyu): BTS, Blackpink, Parasite (2019, first non-English Best Picture Oscar), Squid Game (Netflix's most-watched series), Han Kang (Nobel Literature 2024).",
    fun: "Koreans traditionally counted age differently — everyone turned a year older on New Year's Day. The law switched to international age in 2023." } },
{ id: "north-korea", name: "North Korea", start: 1948, end: 2025, lat: 39.03, lng: 125.75, r: 200, reg: "ea", ev: "mixed", src: "History of North Korea",
  modern: "Democratic People's Republic of Korea",
  sum: "A hereditary communist dictatorship under three generations of the Kim family — one of the world's most isolated states, with nuclear weapons.",
  places: [["Pyongyang", "capital", 39.03, 125.75], ["Yongbyon", "nuclear complex", 39.8, 125.75]], rel: ["joseon", "south-korea", "ussr", "prc"],
  s: { politics: "Kim Il-sung invaded the South in 1950. Juche ideology ('self-reliance'). Famine in the 1990s ('Arduous March') killed hundreds of thousands. First nuclear test in 2006.",
    society: "Songbun classifies citizens by family loyalty; prison camps hold an estimated tens of thousands. Defectors' memoirs (e.g., In Order to Live) are key sources.",
    economy: "State hackers (Lazarus Group) have stolen billions in cryptocurrency, reportedly funding weapons programs.",
    fun: "North Korea uses its own calendar counting from Kim Il-sung's birth (1912 = Juche 1) — abolished in 2024.",
    debates: "Information is scarce and filtered; claims about the country are hard to verify from any side." } },
{ id: "song", name: "Song Dynasty", start: 960, end: 1279, lat: 34.8, lng: 114.31, r: 1000, reg: "ea", ev: "documented", src: "Song dynasty",
  modern: "China",
  sum: "Perhaps the most economically advanced society on Earth before modern times: paper money, gunpowder weapons, the magnetic compass, movable type, and booming cities.",
  places: [["Kaifeng", "Northern Song capital", 34.8, 114.31], ["Hangzhou", "Southern Song capital", 30.27, 120.15]], rel: ["tang", "mongol", "goryeo"],
  s: { economy: "The world's first government-issued paper money (jiaozi, 1024). Kaifeng and Hangzhou had over a million people; a 'commercial revolution' with restaurants, teahouses, entertainment districts.",
    science: "Bi Sheng's movable type (c. 1040), the magnetic compass used for navigation (by 1117), gunpowder weapons, Su Song's astronomical clock tower (1088).",
    ideas: "Zhu Xi's Neo-Confucianism became orthodoxy for 700 years across East Asia. Civil-service exams opened government to non-aristocrats.",
    art: "Landscape painting; 'Along the River During the Qingming Festival', a 5-meter scroll of street life.",
    food: "Rice from fast-ripening Champa varieties doubled harvests; tea culture and restaurants with menus flourished.",
    legacy: "Foot binding spread among elites in this era — a practice ended only in the 20th century.",
    fun: "Kublai Khan's Yuan conquered the Song in 1279; the last Song child-emperor died when a minister leapt into the sea holding him." } },
{ id: "qing", name: "Qing Dynasty", start: 1644, end: 1912, lat: 39.9, lng: 116.4, r: 1700, reg: "ea", ev: "documented", src: "Qing dynasty",
  modern: "China, Mongolia, Taiwan; claims over Tibet and Xinjiang trace to Qing conquests",
  sum: "China's last imperial dynasty, ruled by Manchus — at its height the world's largest economy, then humiliated by Western powers and toppled in 1911.",
  places: [["Beijing", "Forbidden City", 39.92, 116.39], ["Canton (Guangzhou)", "the only port open to Westerners 1757–1842", 23.13, 113.26]], rel: ["ming", "british", "prc", "japan"],
  s: { politics: "Kangxi and Qianlong emperors doubled China's territory. Opium Wars (1839–42, 1856–60), the Taiping Rebellion (1850–64, perhaps 20–30 million dead — the bloodiest civil war in history), the Boxer Rebellion (1900). The 1911 Xinhai Revolution ended 2,000 years of imperial rule.",
    society: "Han men were forced to wear the Manchu queue hairstyle on pain of death.",
    literature: "Dream of the Red Chamber (Cao Xueqin, 18th c.), considered China's greatest novel.",
    legacy: "Modern China's borders largely match the Qing's. The 'Century of Humiliation' narrative shapes Chinese politics today.",
    fun: "The last emperor, Puyi, abdicated aged 6, became a Japanese puppet ruler, and ended life as a gardener in Communist Beijing — as in the film The Last Emperor (1987)." } },
{ id: "prc", name: "People's Republic of China", start: 1949, end: 2025, lat: 35.0, lng: 104.0, r: 1600, reg: "ea", ev: "documented", src: "History of the People's Republic of China",
  modern: "China",
  sum: "From Mao's revolution, famine and Cultural Revolution to Deng's reforms and the world's second-largest economy — the biggest economic transformation in history.",
  places: [["Beijing", "capital", 39.9, 116.4], ["Shanghai", "financial center", 31.23, 121.47], ["Shenzhen", "first Special Economic Zone (1980)", 22.54, 114.06], ["Tiananmen Square", "Beijing", 39.9, 116.39]],
  rel: ["qing", "taiwan", "ussr", "north-korea"],
  s: { politics: "The Great Leap Forward famine (1959–61) killed perhaps 15–45 million. The Cultural Revolution (1966–76). Deng Xiaoping's 'reform and opening' from 1978. Tiananmen Square crackdown (1989). Hong Kong returned in 1997. Xi Jinping since 2012.",
    economy: "~800 million people lifted out of extreme poverty (World Bank). The 'world's factory'; leader in EVs, solar panels, high-speed rail (more than the rest of the world combined).",
    society: "One-child policy (1980–2015). Mass internal migration to cities. Internment of Uyghurs in Xinjiang widely documented and condemned.",
    food: "Regional cuisines — Sichuan, Cantonese, Shandong, Hunan... — 'Chinese food' abroad is mostly Cantonese-American.",
    legacy: "TikTok (ByteDance), WeChat, DJI drones, Huawei; China's space station Tiangong.",
    fun: "China uses a single time zone — in far-west Xinjiang the sun can rise around 10 am Beijing time." } },
{ id: "taiwan", name: "Taiwan", start: 1949, end: 2025, lat: 23.7, lng: 121.0, r: 150, reg: "ea", ev: "documented", src: "History of Taiwan",
  modern: "Taiwan (Republic of China); its status is disputed by the PRC",
  sum: "An island of Austronesian origin, ruled by Dutch, Qing and Japanese before the Nationalists retreated there in 1949 — now a democracy that makes most of the world's advanced chips.",
  places: [["Taipei", "capital", 25.03, 121.57], ["Hsinchu", "TSMC headquarters", 24.8, 120.97]], rel: ["qing", "prc", "japan", "polynesia"],
  s: { origins: "Taiwan's Indigenous peoples are Austronesian — linguists think Austronesian languages (from Malagasy to Hawaiian) originated here.",
    politics: "Japanese colony 1895–1945. Chiang Kai-shek's KMT imposed martial law (1949–87) including the White Terror. Democratic since the 1990s; first Asian country to legalize same-sex marriage (2019). The PRC claims Taiwan; few states formally recognize the ROC.",
    economy: "TSMC manufactures ~90% of the world's most advanced semiconductors — the 'silicon shield'.",
    food: "Bubble tea (1980s), beef noodle soup, night markets, xiaolongbao (Din Tai Fung).",
    fun: "The National Palace Museum in Taipei holds ~700,000 imperial treasures evacuated from Beijing's Forbidden City during the civil war." } },
{ id: "japan-shogun", name: "Shogunate Japan (Kamakura to Edo)", start: 1185, end: 1868, lat: 35.68, lng: 139.69, r: 500, reg: "ea", ev: "documented", src: "Shogun",
  modern: "Japan",
  sum: "Seven centuries of samurai government — civil war, unification, and then 250 years of Edo peace and isolation that produced haiku, kabuki, ukiyo-e and sushi.",
  places: [["Kamakura", "first shogunate", 35.32, 139.55], ["Edo (Tokyo)", "Tokugawa capital", 35.68, 139.69], ["Sekigahara", "decisive battle 1600", 35.37, 136.47], ["Dejima", "Nagasaki, Dutch trading post", 32.74, 129.87]],
  rel: ["heian", "mongol", "joseon", "japan"],
  s: { politics: "Minamoto no Yoritomo's Kamakura shogunate (1185); Mongol invasions defeated (1274, 1281). Sengoku 'warring states' era; unification by Oda Nobunaga, Toyotomi Hideyoshi and Tokugawa Ieyasu (Sekigahara, 1600). Sakoku isolation policy: only the Dutch and Chinese could trade, at Nagasaki. Commodore Perry's 'black ships' forced opening (1853).",
    religion: "Zen Buddhism shaped the tea ceremony, rock gardens and samurai culture. Christianity, brought by Jesuit Francis Xavier (1549), was banned and persecuted.",
    literature: "Bashō's haiku ('An old pond / a frog jumps in / the sound of water'), The Tale of the Heike, Chikamatsu's puppet plays.",
    art: "Ukiyo-e woodblock prints — Hokusai's Great Wave (c. 1831) influenced Van Gogh and Monet ('Japonisme').",
    food: "Nigiri sushi, tempura (from Portuguese cooking), soba — Edo street food.",
    legacy: "Samurai, ninja, katana, bushido (largely romanticized in the 1900s), Shogun (novel and 2024 TV series), Akira Kurosawa's films.",
    fun: "Tokugawa Japan had high literacy and Edo may have been the world's largest city around 1720 (~1 million)." } },
{ id: "japan", name: "Modern Japan", start: 1868, end: 2025, lat: 36.2, lng: 138.25, r: 600, reg: "ea", ev: "documented", src: "History of Japan",
  modern: "Japan",
  sum: "From the Meiji Restoration to imperial expansion, atomic devastation, and the postwar economic miracle — a global cultural force from Toyota to anime.",
  places: [["Tokyo", "capital (~37 million metro, world's largest)", 35.68, 139.69], ["Hiroshima", "atomic bombing 1945", 34.39, 132.45], ["Kyoto", "former imperial capital", 35.01, 135.77], ["Fukushima", "2011 nuclear disaster", 37.42, 141.03]],
  rel: ["japan-shogun", "qing", "south-korea", "usa"],
  s: { politics: "Meiji modernization; defeated China (1895) and Russia (1905) — the first modern Asian victory over a European power. Colonized Taiwan and Korea; invaded China (Nanjing Massacre, 1937); Pearl Harbor (1941); atomic bombings and surrender (1945). US-drafted pacifist constitution (Article 9).",
    economy: "Postwar miracle: Sony, Toyota (lean manufacturing), Nintendo; the bullet train (Shinkansen, 1964). Asset bubble burst in 1991 → 'Lost Decades'.",
    society: "World's oldest population; ~30% over 65. Ultra-low crime and lost wallets usually returned.",
    food: "Ramen (Chinese-origin), instant noodles, curry rice (via British navy), tonkatsu, washoku is UNESCO heritage.",
    legacy: "Anime and manga (Studio Ghibli, Dragon Ball, One Piece), Pokémon (highest-grossing media franchise ever), emoji (1999, from the Japanese 'e' picture + 'moji' character), karaoke, video games.",
    fun: "Japan has more than 1,000 businesses older than 200 years; Kongō Gumi, a temple builder, operated from 578 CE until 2006." } }
);
